classDiagram
    direction LR
    class ProjectChangeCursor {
        +String projectId
        +long revision
    }
    class VersionedResource {
        +String resourceKind
        +String resourceId
        +long version
    }
    class ResourceMutation {
        +String operationId
        +ResourceRef[] readSet
        +ResourceRef[] writeSet
    }
    class ResourceConflict {
        +String resourceKind
        +String resourceId
        +long expectedVersion
        +long currentVersion
    }
    class ResourceIntent {
        +String agentRunId
        +String resourceKind
        +String resourceId
        +DateTime expiresAt
    }
    class MemoryNote {
        +String noteId
        +String operationId
        +String runId
        +long taskId
        +String body
    }
    class CanonicalMemory {
        +long version
        +String summary
    }

    ResourceMutation --> VersionedResource : conditionally updates
    ResourceMutation --> ResourceConflict : returns on overlap
    ResourceIntent ..> VersionedResource : advisory only
    ProjectChangeCursor ..> VersionedResource : signals committed changes
    CanonicalMemory "1" --> "*" MemoryNote : compacts
